UPDATE favorites
SET deleted_at = NOW()
WHERE user_id = #{userId}
  AND accommodation_id = #{accommodationId}
  AND deleted_at IS NULL

mapper.select:
SELECT favorite_id, user_id, accommodation_id, created_at, deleted_at
FROM favorites
WHERE user_id = #{userId}
  AND accommodation_id = #{accommodationId}
  AND deleted_at IS NULL

